const FX_LIST = Object.entries(ALL_EFFECTS_MAP).map(([id, mod]) => {
  const meta = { fps: 30, bg: "proton_diquis", loop: false, duration: 1, tags: [], options: {}, ...mod.meta };
  return { id, cat: id.split("/")[0], name: meta.name, mod: { ...mod, meta }, meta };
});

